"use strict";

/**
 * created the canvas
*/
function setup() {

    createCanvas(900,700);
    background(25,20,216);

}


/**
 * drew my art masterpiece
*/
function draw() {
    background(25,20,216);
    fill(29,99,499);
    stroke(515,345,55);
    strokeWeight(4);


    rect(20,50,30,150);
    rect(20,250,50,150);
        rect(20,450,30,150);

      ellipse(120, 220, 40, 380);
       ellipse(320, 420, 420, 380);
     ellipse(220, 220, 40, 380);
       ellipse(420, 420, 420, 380);
        ellipse(320, 220, 40, 380);
       ellipse(520, 420, 420, 380);

        rect(820,50,30,150);
    rect(820,250,50,150);
         rect(820,450,30,150);



}